mapper.update:
UPDATE analysis_reference
   SET status = #{status}
     , fail_reason = #{failReason}
 WHERE reference_id = #{referenceId}

mapper.delete:
DELETE FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type IN ('OVERRIDES', 'CALLS_POSSIBLE_IMPLEMENTATION')

mapper.sql:
 WHERE m.revision_id = #{revisionId}
AND s.fqn LIKE '%' || #{owner} || '%'
AND m.name = #{name}

mapper.select:
SELECT 
  FROM analysis_method m
  JOIN analysis_symbol s ON s.revision_id = m.revision_id AND s.symbol_id = m.owner_symbol_id
  JOIN analysis_file f ON f.file_id = m.file_id
 WHERE m.revision_id = #{revisionId}
   AND m.method_id = #{methodId}
